  'Politisk Eksponeret Person (PEP)': 'Politically Exposed Person (PEP)',
  'En PEP er en person, der beklæder eller har beklædt en fremtrædende offentlig stilling, fx statsledere, ministre, parlamentsmedlemmer, højtstående embedsmænd eller ledende personer i internationale organisationer.': 'A PEP is a person who holds or has held a prominent public position, e.g. heads of state, ministers, members of parliament, senior civil servants or senior figures in international organisations.',
  'PEP-kontrol er lovpligtig under hvidvasklovens §§ 14-18 og kræver skærpet kundekendskab (Enhanced Due Diligence) ved konstatering af PEP-status. Crediwire foretager automatisk opslag og gemmer tidsstemplet kontrol-log.': 'PEP screening is a legal requirement under sections 14-18 of the Danish AML Act and requires enhanced due diligence where PEP status is established. Crediwire performs automatic lookups and stores a timestamped audit log.',
