  'NordHavn Composites A/S producerer avancerede kompositelementer til vindmølleindustrien med speciale i store offshore-vinger (80-115 m). Selskabets kernekompetence er high-precision finishing og tolerancestyring, der adskiller dem fra lavpriskonkurrenter i Østeuropa.': "NordHavn Composites A/S manufactures advanced composite components for the wind turbine industry, specialising in large offshore blades (80-115 m). The company's core competence is high-precision finishing and tolerance control, setting it apart from low-cost competitors in Eastern Europe.",
