  "EIFO bruger Crediwire til at indsamle materialet sikkert. Crediwire behandler det på vegne af EIFO og kun til jeres ansøgning.": "EIFO uses Crediwire to collect the material securely. Crediwire processes it on behalf of EIFO and only for your application.",
  "EIFO bruger Crediwire til sikker indsamling af materiale, derfor ligger siden hos Crediwire. Kun Mette og hendes kolleger hos EIFO ser det, I sender.": "EIFO uses Crediwire for secure collection of material, which is why this page is on Crediwire. Only Mette and her colleagues at EIFO see what you send.",
