  "EIFO får kun læseadgang til": "EIFO only gets read access to",
  "EIFO kan hente kontoplan, saldobalance og periodetal løbende, indtil I trækker adgangen tilbage.": "EIFO can fetch the chart of accounts, trial balance and interim figures on an ongoing basis until you revoke access.",
  "EIFO kan hente kontoplan, saldobalance og periodetal til og med kreditbeslutningen, dog højst til {date}.": "EIFO can fetch the chart of accounts, trial balance and interim figures until the credit decision, and no later than {date}.",
