  "Søgeresultater": "Search results",
  "Tak for jeres ansøgning om {type} hos EIFO. For at vi kan vurdere den, har vi brug for materialet nedenfor. I sender det via linket i denne mail. Det går til Crediwire, som EIFO bruger til sikker indsamling af materiale.\n\nDet tager ca. 10 minutter. Frist: {date}.\n\nRing eller skriv, hvis noget er uklart.\n\nVenlig hilsen\nMette Larsen\nEIFO": "Thank you for your {type} application with EIFO. To assess it, we need the material below. You send it via the link in this email. It goes to Crediwire, which EIFO uses for secure collection of material.\n\nIt takes about 10 minutes. Deadline: {date}.\n\nCall or write if anything is unclear.\n\nKind regards\nMette Larsen\nEIFO",
  "Tak, {name}. Materialet er sendt til EIFO.": "Thank you, {name}. The material has been sent to EIFO.",
