  'Punktet er allerede godkendt. Fravælger du det, bliver kunden ikke længere bedt om det, når du sender opdateringen. Filerne bliver liggende under Dokumenter.': 'The item is already approved. If you deselect it, the customer will no longer be asked for it when you send the update. The files stay under Documents.',
