  'Ret i kladden. Kunden ser kun det, du allerede har sendt, indtil du trykker Send opdatering.': 'Edit the draft. The customer only sees what you have already sent until you press Send update.',
  'Sag {nr} ({type}) er en separat sag for {name}. Demoen har kun data for sag {live}, så denne sag vises uden indhold og deler ikke tilstand med den.': 'Case {nr} ({type}) is a separate case for {name}. The demo only has data for case {live}, so this case is shown without content and does not share state with it.',
  'Sagen blev oprettet i demoen {date}, men har endnu hverken materiale, anmodning eller memo. I en rigtig sag ville du fortsætte med at vurdere de offentlige data.': 'The case was created in the demo on {date} but has no material, request or memo yet. In a real case you would continue by assessing the public data.',
  'Sagen er flyttet til {name}': 'The case has been reassigned to {name}',
  'Sagen er genoptaget i fasen {stage}': 'The case has been reopened in the {stage} stage',
