  'Sagen er oprettet, men ikke udfyldt': 'The case is created but not filled in',
  'Sagen findes ikke': 'The case does not exist',
  'Sagen findes ikke i demoen. Den kan være slettet, eller linket kan være forkert.': 'The case does not exist in the demo. It may have been deleted, or the link may be wrong.',
  'Sagen går direkte til memo og indstilling uden nyt materiale fra kunden. Din begrundelse står i klarhedstjekket og i indstillingen.': 'The case goes straight to memo and submission without new material from the customer. Your reason appears in the readiness check and in the submission.',
  'Sagen indstilles på det offentlige grundlag og de dokumenter, der allerede findes.': 'The case is submitted on the public data and the documents already on file.',
  'Sagen kan først indstilles, når materialet er godkendt, alle memoets afsnit er gennemgået, og ingen blokerende kommentarer står åbne. Tomme felter og passerede datoer kan du indstille med, men hvert punkt kræver en begrundelse. Memoet fryses som en version, når du indstiller.': 'The case can only be submitted when the material is approved, every memo section has been reviewed and no blocking comments are open. You can submit with empty fields and passed dates, but each item needs a reason. The memo is frozen as a version when you submit.',
  'Sagen stoppes i fasen {stage}. Kunden får ikke besked automatisk. Genoptager du sagen, vender den tilbage hertil.': 'The case is stopped in the {stage} stage. The customer is not notified automatically. If you reopen the case, it returns here.',
