  "Opdateringen efterlader ingen påkrævede punkter.": "The update leaves no required items.",
  "Opdateringen fjerner alle påkrævede punkter, så kunden kun bliver bedt om valgfrit materiale. Sagen går til Klar, når det modtagne er gennemgået. Vil du sende den alligevel?": "The update removes all required items, so the customer is only asked for optional material. The case moves to Ready once what has been received is reviewed. Do you want to send it anyway?",
  "Ret i kladden. Kunden ser kun det, du allerede har sendt, indtil du trykker Send opdatering. Sagens fase er uændret.": "Edit the draft. The customer only sees what you have already sent until you press Send update. The case stage is unchanged.",
  "Sagen er indstillet til kreditkomitéen uden nyt materiale fra kunden.": "The case has been submitted to the credit committee without new material from the customer.",
  "Sagen kan først indstilles, når materialet er godkendt, alle memoets afsnit er gennemgået, og ingen blokerende kommentarer står åbne. Manglende sagsdata og passerede datoer kan du indstille med, men hvert punkt kræver en begrundelse. Rene skabelonfelter dækkes af én begrundelse, og komitéens egne felter tæller ikke med. Memoet fryses som en version, når du indstiller.": "The case can only be submitted when the material is approved, all memo sections are reviewed and no blocking comments are open. You can submit with missing case data and passed dates, but each item needs a reason. Plain template fields are covered by one reason, and the committee's own fields do not count. The memo is frozen as a version when you submit.",
